84	// arrayField 是一个已识别的对象数组字段：name 为标准字段名，elem 为数组元素
85	// 所在层次的 schema。
86	type arrayField struct {
87		name string
88		elem *objectSchema
89	}
90	
91	var (
92		// 日志条目层次：log[i] 与 requests[r].entries[i] 是同一种对象。
93		entryObjectSchema = &objectSchema{numerics: []string{"index", "term"}}
94		// 复制请求层次：数值字段外还嵌套 entries 条目数组。
95		requestObjectSchema = &objectSchema{
96			numerics: []string{"term", "prevLogIndex", "prevLogTerm", "leaderCommit"},
97			arrays:   []arrayField{{name: "entries", elem: entryObjectSchema}},
98		}
99		// 根输入层次：初始状态的数值字段外还嵌套 log 与 requests 两个数组。
100		rootObjectSchema = &objectSchema{
101			numerics: []string{"currentTerm", "committedIndex"},
102			arrays: []arrayField{
103				{name: "log", elem: entryObjectSchema},
104				{name: "requests", elem: requestObjectSchema},
105			},
106		}
107	)
108	
109	// numericName 在 key 命中本层次某个已识别数值字段时返回它的标准拼写。
110	func (s *objectSchema) numericName(key string) (string, bool) {
111		for _, name := range s.numerics {
112			if strings.EqualFold(key, name) {
113				return name, true
114			}
115		}
116		return "", false
117	}
118	
119	// arrayField 在 key 命中本层次某个已识别数组字段时返回它的定义（含标准拼写）。
120	func (s *objectSchema) arrayField(key string) (arrayField, bool) {
