122			if strings.EqualFold(key, field.name) {
123				return field, true
124			}
125		}
126		return arrayField{}, false
127	}
128	
129	// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
130	// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
131	// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
132	// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
133	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
134	// requests[1].leaderCommit。
135	//
136	// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
137	// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
138	// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
139	// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
140	// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
141	// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
142	// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
143	func nullNumericFieldPath(data []byte) string {
144		dec := json.NewDecoder(bytes.NewReader(data))
145	
146		// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
147		// 字段位置，交由随后的类型化解码产出既有的解析错误。
148		tok, err := dec.Token()
149		if err != nil || tok != json.Delim('{') {
150			return ""
151		}
152		return scanObjectFields(dec, rootObjectSchema, "")
153	}
154	
155	// scanObjectFields 扫描一个已读入起始 '{' 的对象的字段流，prefix 是该对象
156	// 的位置前缀（根对象为空，其余层次以 "." 结尾，如 "requests[1]."）。每个键
157	// 按所在层次的 schema 分派：已识别数值字段检查是否写成 null，已识别数组字段
158	// 递归扫描元素，其余键的值整体跳过。返回第一个数值 null 的完整位置。
159	func scanObjectFields(dec *json.Decoder, schema *objectSchema, prefix string) string {
160		for dec.More() {
161			key, ok := decodeKey(dec)
162			if !ok {
163				return ""
164			}
165			if name, ok := schema.numericName(key); ok {
166				if nullScalarPath(dec) {
167					return prefix + name
168				}
169				continue
170			}
171			if field, ok := schema.arrayField(key); ok {
172				if path := scanObjectArray(dec, field.elem, prefix+field.name); path != "" {
173					return path
174				}
175				continue
176			}
177			skipValue(dec)
178		}
179		return ""
180	}
181	
182	// scanObjectArray 扫描一个对象数组字段的完整 token 流（数组字段重复出现时由
183	// 调用方对每一份数组分别调用），arrayPath 是数组自身的位置（如 "log" 或
184	// "requests[r].entries"），返回第一个数值 null 的完整位置。
185	func scanObjectArray(dec *json.Decoder, elem *objectSchema, arrayPath string) string {
186		tok, err := dec.Token()
187		if err != nil {
188			return ""
189		}
190		if tok != json.Delim('[') {
191			// 数组字段本身为 null 或其他类型（如被写成对象）：沿用既有处理，
192			// 类型错误由随后的类型化解码按既有格式报告。这里必须把整个值消费
193			// 完——起始分隔符已经读出，若就此返回，调用方的循环会落到对象内部，
194			// 把其中的 term/index 等字段当成外层已识别字段，其后的真实数值
195			// null 也会被漏检。
196			if d, ok := tok.(json.Delim); ok {
197				skipRest(dec, d)
198			}
199			return ""
200		}
201		for i := 0; dec.More(); i++ {
202			tok, err := dec.Token()
203			if err != nil {
204				return ""
205			}
206			if tok != json.Delim('{') {
207				// 非对象元素不可能含已识别字段；若它本身是容器仍要消费完整。
208				if d, ok := tok.(json.Delim); ok {
209					skipRest(dec, d)
210				}
211				continue
212			}
213			prefix := fmt.Sprintf("%s[%d].", arrayPath, i)
214			if path := scanObjectFields(dec, elem, prefix); path != "" {
215				return path
216			}
217			if _, err := dec.Token(); err != nil { // 元素对象的 '}'
218				return ""
219			}
220		}
221		if _, err := dec.Token(); err != nil { // 数组的 ']'
222			return ""
223		}
224		return ""
225	}
226	
227	// decodeKey 读取并断言下一个 token 是对象键。
228	func decodeKey(dec *json.Decoder) (string, bool) {
229		tok, err := dec.Token()
230		if err != nil {
231			return "", false
232		}
233		key, ok := tok.(string)
234		return key, ok
235	}
236	
237	// nullScalarPath 消费一个已识别数值字段的值 token 流，报告该次出现是否被
238	// 显式写成 null。值为对象或数组时整体跳过（结构异常的输入留给类型化解码
239	// 报告既有错误）。
240	func nullScalarPath(dec *json.Decoder) bool {
241		tok, err := dec.Token()
242		if err != nil {
243			return false
244		}
245		if tok == nil {
246			return true
247		}
248		if d, ok := tok.(json.Delim); ok {
249			skipRest(dec, d)
250		}
251		return false
252	}
253	
254	// skipValue 读取并消费一个完整的 JSON 值（标量或容器）。
255	func skipValue(dec *json.Decoder) {
256		tok, err := dec.Token()
257		if err != nil {
258			return
259		}
260		if d, ok := tok.(json.Delim); ok {
261			skipRest(dec, d)
262		}
263	}
264	
265	// skipRest 消费一个容器剩余的 token 流，open 是已经读出的起始分隔符；
266	// 起始分隔符不是 '{' / '[' 时无需消费，直接返回。
267	func skipRest(dec *json.Decoder, open json.Delim) {
268		if open != '{' && open != '[' {
269			return
270		}
271		depth := 1
272		for depth > 0 {
273			tok, err := dec.Token()
274			if err != nil {
275				return
276			}
277			if d, ok := tok.(json.Delim); ok {
278				switch d {
279				case '{', '[':
280					depth++
281				case '}', ']':
282					depth--
283				}
284			}
285		}
286	}
