107	// 不接受正号、空白、小数、指数形式或非 ASCII 数字，空字符串也不是整数；
108	// 超出 int64 范围同样失败。先逐字节校验形状，再交给 strconv 判定范围。
109	func parseKVInt(s string) (int64, bool) {
110		digits := s
111		if strings.HasPrefix(digits, "-") {
112			digits = digits[1:]
113		}
114		if digits == "" {
115			return 0, false
116		}
117		for i := 0; i < len(digits); i++ {
118			if digits[i] < '0' || digits[i] > '9' {
119				return 0, false
120			}
121		}
122		value, err := strconv.ParseInt(s, 10, 64)
123		if err != nil {
